<?php
require_once __DIR__.'/includes/config.php';require_once __DIR__.'/includes/db.php';require_once __DIR__.'/includes/functions.php';require_once __DIR__.'/includes/security.php';require_once __DIR__.'/includes/auth.php';if(is_logged_in())redirect('index.php');$errors=[];$old=['full_name'=>'','email'=>'','role'=>'customer','phone'=>'','address'=>'','district'=>'','business_name'=>''];if($_SERVER['REQUEST_METHOD']==='POST'){csrf_protect();$old=array_merge($old,array_intersect_key($_POST,$old));$p=$_POST['password']??'';$pc=$_POST['password_confirm']??'';if($p!==$pc)$errors[]='Passwords do not match.';else{$r=register_user($pdo,array_merge($old,['password'=>$p]));if($r['success']){set_flash('success','Account created successfully. Please log in.');redirect('login.php');}$errors[]=$r['error'];}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Register — <?=e(SITE_NAME)?></title><link rel="stylesheet" href="<?=e(SITE_URL)?>/styles.css"></head><body><div class="auth-page"><div class="auth-card"><h1><?=e(SITE_NAME)?></h1><h2>Create an account</h2><?php if($errors):?><div class="flash-message flash-error"><?php foreach($errors as $err):?><p><?=e($err)?></p><?php endforeach;?></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Account type<select name="role" id="role" onchange="document.getElementById('sme-fields').hidden=this.value!=='sme'"><option value="customer" <?=$old['role']==='customer'?'selected':''?>>Customer</option><option value="sme" <?=$old['role']==='sme'?'selected':''?>>SME / Seller</option></select></label><label>Full name<input name="full_name" value="<?=e($old['full_name'])?>" required></label><label>Email<input type="email" name="email" value="<?=e($old['email'])?>" required></label><label>Phone<input name="phone" value="<?=e($old['phone'])?>"></label><label>District<select name="district"><option value="">Select district</option><?php foreach(MAURITIUS_DISTRICTS as $d):?><option <?=$old['district']===$d?'selected':''?>><?=e($d)?></option><?php endforeach;?></select></label><label>Address<input name="address" value="<?=e($old['address'])?>"></label><div id="sme-fields" <?=$old['role']==='sme'?'':'hidden'?>><label>Business name<input name="business_name" value="<?=e($old['business_name'])?>"></label></div><label>Password<input type="password" name="password" required></label><label>Confirm password<input type="password" name="password_confirm" required></label><button class="btn-primary">Create account</button></form><p>Already have an account? <a href="login.php">Log in</a></p></div></div></body></html>